#!/usr/bin/env bash
# Muzey: Telegram orqali ro'yxatdan o'tish, har bir foydalanuvchiga alohida muzey va profil,
# doimiy kirish havolasi, sevgilisi uchun ulashish havolasi.
# Ishlatish: repo papkasida (manage.py yonida):  bash apply_muzey2.sh
# Eslatma: pastdagi fayllar TO'LIQ almashtiriladi; eskilari muzey_backup_<vaqt>/ ichiga saqlanadi.
set -e
if [ ! -f manage.py ] || [ ! -d gallery ]; then echo "Xato: skriptni repo papkasida (manage.py yonida) ishga tushiring."; exit 1; fi

BK="muzey_backup_$(date +%Y%m%d_%H%M%S)"; mkdir -p "$BK"
TMP="$(mktemp)"
base64 -d > "$TMP" <<'B64_EOF'

B64_EOF
for f in $(tar tzf "$TMP"); do if [ -f "$f" ]; then mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; fi; done
tar xzf "$TMP"; rm -f "$TMP"
for f in access/middleware.py access/templates/access/manage.html; do if [ -f "$f" ]; then mkdir -p "$BK/$(dirname "$f")"; mv "$f" "$BK/$f"; fi; done
echo "✓ Fayllar yozildi (eski nusxalar: $BK/ — GitHub'ga qo'shmang, kerak bo'lmasa o'chirib tashlang)"

if python3 -c "import django, dotenv, dj_database_url" 2>/dev/null; then
  python3 manage.py migrate && echo "✓ Migratsiya bajarildi."
else
  echo "Kutubxonalar yo'q. Avval:  source venv/bin/activate && pip install -r requirements.txt"
  echo "Keyin:                     python manage.py migrate"
fi
cat <<'MSG'

Render (yoki .env) da quyidagi o'zgaruvchilar bo'lishi kerak:
  TELEGRAM_BOT_TOKEN      — @BotFather bergan token
  TELEGRAM_BOT_USERNAME   — botning username'i (@ belgisiz)
  SITE_URL                — sayt manzili, masalan https://muzey.onrender.com
  TELEGRAM_OWNER_IDS      — (ixtiyoriy) sizning Telegram ID'ingiz: eski muzey va admin profilingiz shunga bog'lanadi
Webhook'ni o'rnatish:  python manage.py set_webhook
Sinov:                 python manage.py test gallery
MSG
